files.block.c:
#include "block.h"
Block make_block(double seed) { return (Block){{seed,seed+1,seed+2}}; }
Block increment_block(Block block) { for(int i=0;i<3;i++) block.values[i] += 10; return block; }
Small make_small(float seed) { return (Small){{seed,seed+1}}; }
Nested make_nested(double seed) { return (Nested){make_block(seed)}; }
Ints make_ints(int seed) { return (Ints){{seed,seed+1}}; }

