from std.testing import assert_equal
from bindings import make_block, increment_block, make_small, make_nested, make_ints
def main() raises:
    var first = make_block(2.0)
    assert_equal(first.values[0], 2.0)
    assert_equal(first.values[2], 4.0)
    var second = increment_block(first)
    assert_equal(second.values[0], 12.0)
    assert_equal(second.values[2], 14.0)
    var small = make_small(5.0)
    assert_equal(small.values[0], 5.0)
    assert_equal(small.values[1], 6.0)
    var nested = make_nested(7.0)
    assert_equal(nested.block.values[2], 9.0)
    var ints = make_ints(11)
    assert_equal(ints.values[0], 11)
    assert_equal(ints.values[1], 12)
    print("Mojo 1.2 C aggregate returns passed")
